root.addEventListener('click',e=>{const action=e.target.closest('button')?.dataset.action;if(action==='trace-select'){showDialog('Drive selection','<div class="trace-drive-dialog"><div><button data-action="trace-drive-info">C:\</button></div><section id="trace-drive-info">...</section></div>','<button class="primary compact" data-action="trace-drive-accept" disabled>Select</button><button class="secondary compact" data-action="close-dialog">Cancel</button>');document.getElementById('lab-dialog').classList.add('native-properties-dialog');}if(action==='trace-drive-info'){document.getElementById('trace-drive-info').innerHTML='<dl><dt>Name</dt><dd>C:\</dd><dt>Root</dt><dd>C:\</dd><dt>Format</dt><dd>NTFS</dd><dt>Type</dt><dd>Fixed</dd><dt>Total size</dt><dd>84 GB</dd></dl>';document.querySelector('[data-action=trace-drive-accept]').disabled=false;}if(action==='trace-drive-accept'){windows.get(tool).traceDrive='C:';document.getElementById('lab-dialog').close();renderApp();}if(action==='trace-scan'){const w=windows.get(tool);if(!w.traceDrive){toast('Önce Drive → Select ile sürücü seç.');return;}w.traceScanning=true;renderApp();const sid=state.session.id;setTimeout(()=>{if(state.session.id!==sid)return;w.traceScanning=false;w.traceReady=true;if(tool==='journaltrace')renderApp();},900);}if(action==='trace-filters')document.getElementById('tool-query')?.focus();if(action==='trace-language')toast('JournalTrace arayüz dili: English');});
